import { useEffect, useState } from 'react';
import ReactMarkdown from 'react-markdown';
import { ChevronUp, Sparkles } from 'lucide-react';
import { api, type Post } from '../lib/api';

// Overviews already fetched this session, keyed by post version.
const cache = new Map<string, string>();

/** "✨ AI overview" button that explains a project, generated by the backend and cached there. */
export default function AIOverview({ post }: { post: Post }) {
  const key = `${post._id}:${post.updated_at ?? ''}`;
  const [open, setOpen] = useState(false);
  const [text, setText] = useState<string | null>(cache.get(key) ?? null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    setOpen(false);
    setText(cache.get(key) ?? null);
    setError('');
  }, [key]);

  const toggle = async () => {
    if (open) return setOpen(false);
    setOpen(true);
    if (text || loading) return;
    setLoading(true);
    setError('');
    try {
      const res = await api<{ overview: string }>(`/projects/${post._id}/overview`);
      cache.set(key, res.overview);
      setText(res.overview);
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Could not load the overview');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="rounded-xl p-[1px] bg-gradient-to-r from-orange-500 via-pink-500 to-purple-500">
      <div className="rounded-[11px] bg-white dark:bg-gray-950">
        <button onClick={toggle} aria-expanded={open} className="w-full flex items-center gap-2 px-4 py-2.5 text-sm font-semibold">
          <Sparkles size={16} className="text-pink-500" />
          <span className="bg-gradient-to-r from-orange-500 to-pink-500 bg-clip-text text-transparent">AI overview</span>
          <span className="ml-auto text-xs font-normal text-gray-500">{open ? <ChevronUp size={16} /> : 'What is this project?'}</span>
        </button>
        {open && (
          <div className="px-4 pb-4 text-sm text-gray-700 dark:text-gray-300">
            {loading && (
              <div className="space-y-2 animate-pulse" aria-label="Generating overview">
                <div className="h-3 rounded bg-gray-200 dark:bg-gray-800 w-11/12" />
                <div className="h-3 rounded bg-gray-200 dark:bg-gray-800 w-10/12" />
                <div className="h-3 rounded bg-gray-200 dark:bg-gray-800 w-8/12" />
                <p className="text-xs text-gray-500 pt-1">Reading the project...</p>
              </div>
            )}
            {error && <p className="text-red-500">{error}</p>}
            {text && (
              <div className="space-y-2 [&_ul]:list-disc [&_ul]:pl-5 [&_ul]:space-y-1 [&_strong]:text-black dark:[&_strong]:text-white [&_a]:text-blue-500">
                <ReactMarkdown>{text}</ReactMarkdown>
                <p className="text-[11px] text-gray-500 pt-1">Generated by AI from this post and Shivam's notes.</p>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}
